using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.ComponentModel;using CodexKit.Native;
namespace CodexKit {
internal static class ProcessTerminationTests {
    static void Require(bool value,string message){if(!value)throw new InvalidDataException(message);}
    static ProcessIdentity P(int id,int parent,string path,string owner="fixture",int session=7,long started=100){return new ProcessIdentity{Id=id,ParentId=parent,Path=path,Name=Path.GetFileNameWithoutExtension(path),Owner=owner,SessionId=session,Started=started};}
    sealed class Processes:INativeProcesses {
        internal List<ProcessIdentity> Entries=new List<ProcessIdentity>(),Terminated=new List<ProcessIdentity>(),Tracked;internal Func<ProcessIdentity,Exception> Failure;internal List<ProcessIdentity> Remaining=new List<ProcessIdentity>();
        public List<ProcessIdentity> List(NativePaths p,OfficialDesktop d){return Entries.ToList();}public List<ProcessIdentity> RuntimeUsers(NativePaths p,OfficialDesktop d){return Entries.ToList();}
        public void Terminate(ProcessIdentity p){Terminated.Add(p);var error=Failure==null?null:Failure(p);if(error!=null)throw error;Entries.RemoveAll(x=>x.Key==p.Key);}
        public List<ProcessIdentity> Wait(NativePaths p,OfficialDesktop d,IEnumerable<ProcessIdentity> tracked,int timeout){Tracked=tracked.ToList();Require(timeout==10000,"wrong confirmation timeout");return Remaining.ToList();}
    }
    static string Failure(Action body){try{body();}catch(Exception ex){return ex.Message;}throw new InvalidDataException("Expected termination failure");}
    internal static void Run(Action<string,Action> check){
        var paths=new NativePaths{Home=@"C:\fixture\home",LocalData=@"C:\fixture\local",UserTools=@"C:\fixture\tools",Documents=@"C:\fixture\docs"};var app=new OfficialDesktop{Install=@"C:\official"};
        var main=P(1,0,@"C:\official\app\ChatGPT.exe");var child=P(2,1,Path.Combine(paths.RuntimeRoot,"id","bin","node.exe"));var relocated=P(3,1,Path.Combine(paths.LocalData,"OpenAI","Codex","bin","id","codex.exe"));var companion=P(4,3,Path.Combine(paths.Home,"packages","standalone","current","bin","codex-code-mode-host.exe"));
        var inventory=new[]{main,child,relocated,companion,P(5,0,Path.Combine(paths.Home,"packages","standalone","current","bin","codex.exe")),P(6,0,@"C:\other\ChatGPT.exe"),P(7,1,@"C:\other\node.exe"),P(8,0,Path.Combine(paths.RuntimeRoot,"id","bin","node.exe")),P(9,0,main.Path,"other-user"),P(10,0,main.Path,"fixture",8),P(11,1,@"C:\other\chrome.exe"),P(12,0,@"C:\official\app\codex-command-runner.exe")};
        check("process_targets_require_desktop_ancestry_and_known_paths",()=>{var selected=WindowsNativeProcesses.SelectTargets(inventory,paths,app,"fixture",7,null);Require(selected.Select(p=>p.Id).SequenceEqual(new[]{1,2,3,4}),"unrelated application, independent CLI, user or session selected");});
        check("process_snapshot_retains_orphaned_relocated_children",()=>{var selected=WindowsNativeProcesses.SelectTargets(inventory,paths,app,"fixture",7,null);var remaining=WindowsNativeProcesses.SelectTargets(inventory.Where(p=>p.Id!=1),paths,app,"fixture",7,selected);Require(remaining.Select(p=>p.Id).SequenceEqual(new[]{2,3,4}),"orphaned child disappeared or independent CLI was added");});
        check("process_reused_pid_does_not_retain_unrelated_runtime",()=>{var reused=P(3,0,relocated.Path,started:200);Require(WindowsNativeProcesses.SelectTargets(new[]{reused},paths,app,"fixture",7,new[]{relocated}).Count==0,"reused PID accepted as retained target");});
        check("process_identity_requires_pid_start_owner_session_and_path",()=>{Require(WindowsNativeProcesses.SameIdentity(main,P(1,0,main.Path.ToUpperInvariant())),"case-only path rejected");foreach(var changed in new[]{P(2,0,main.Path),P(1,0,main.Path,started:200),P(1,0,main.Path,"other-user"),P(1,0,main.Path,"fixture",8),P(1,0,@"C:\other\ChatGPT.exe")})Require(!WindowsNativeProcesses.SameIdentity(main,changed),"changed identity accepted");});
        check("process_tracked_identity_mismatch_stops_confirmation",()=>{var changed=P(3,0,@"C:\other\codex.exe");Require(Failure(()=>WindowsNativeProcesses.SelectTargets(new[]{changed},paths,app,"fixture",7,new[]{relocated})).Contains("身份"),"unknown retained path accepted");});
        check("process_force_uses_entire_approved_snapshot_and_confirms_exit",()=>{var fake=new Processes{Entries=new List<ProcessIdentity>{child,main,relocated}};NativeProcessWorkflow.EnsureStopped(paths,app,fake,true,fake.Entries.Select(p=>p.Key).ToArray(),delegate{});Require(fake.Terminated.Select(p=>p.Id).SequenceEqual(new[]{1,2,3})&&fake.Tracked.Count==3,"force or orphan confirmation skipped a target");});
        check("process_force_needs_fresh_explicit_authorization",()=>{foreach(bool allowed in new[]{false,true}){var fake=new Processes{Entries=new List<ProcessIdentity>{main}};Failure(()=>NativeProcessWorkflow.EnsureStopped(paths,app,fake,allowed,new[]{"1:99"},delegate{}));Require(fake.Terminated.Count==0,"unapproved target terminated");}});
        check("process_force_reports_permission_failure_with_pid_and_error_code",()=>{var fake=new Processes{Entries=new List<ProcessIdentity>{main},Failure=p=>WindowsNativeProcesses.TerminationFailure(p,"强制结束",new Win32Exception(5))};var message=Failure(()=>NativeProcessWorkflow.EnsureStopped(paths,app,fake,true,new[]{main.Key},delegate{}));Require(message.Contains("PID 1")&&message.Contains("Windows 错误码 5")&&fake.Tracked==null,"permission failure became success or lost context");});
        check("process_force_residual_orphan_is_timeout_not_success",()=>{var fake=new Processes{Entries=new List<ProcessIdentity>{main,relocated},Remaining=new List<ProcessIdentity>{relocated}};var message=Failure(()=>NativeProcessWorkflow.EnsureStopped(paths,app,fake,true,new[]{main.Key,relocated.Key},delegate{}));Require(message.Contains("10 秒")&&message.Contains("PID 3")&&fake.Tracked.Count==2,"orphan reported as exited");});
        check("process_force_new_instance_is_not_silently_killed",()=>{var fresh=P(20,0,main.Path,started:300);var fake=new Processes{Entries=new List<ProcessIdentity>{main},Remaining=new List<ProcessIdentity>{fresh}};var message=Failure(()=>NativeProcessWorkflow.EnsureStopped(paths,app,fake,true,new[]{main.Key},delegate{}));Require(message.Contains("未授权")&&fake.Terminated.Count==1&&fake.Terminated[0].Id==1,"new instance force-closed or accepted");});
        check("process_already_exited_requires_no_force_or_wait",()=>{var fake=new Processes();NativeProcessWorkflow.EnsureStopped(paths,app,fake,false,null,delegate{});Require(fake.Terminated.Count==0&&fake.Tracked==null,"empty target list caused termination");});
    }
}
}
